function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

function availability(library, isbn) {
  const book = library.findBook(isbn);
  if (!book) {
    return 'not found';
  }
  return `${book.copies - book.checkedOut}/${book.copies}`;
}

module.exports = { shelfLine, availability };

